import java.lang.classfile.*;
import java.lang.classfile.attribute.CodeAttribute;
import java.nio.file.*;
import java.util.*;
import java.util.stream.*;

/* Prints every method under a class directory whose bytecode is at least MIN bytes:
 * size, max_locals, max_stack, class and method name.  Usage: java MethodSizes.java <dir> <min> */
public class MethodSizes {
    public static void main(String[] args) throws Exception {
        Path root = Paths.get(args[0]);
        int min = Integer.parseInt(args[1]);
        List<String> rows = new ArrayList<>();
        try (Stream<Path> s = Files.walk(root)) {
            for (Path p : s.filter(f -> f.toString().endsWith(".class")).collect(Collectors.toList())) {
                ClassModel cm;
                try { cm = ClassFile.of().parse(Files.readAllBytes(p)); } catch (Exception e) { continue; }
                for (MethodModel m : cm.methods()) {
                    Optional<CodeAttribute> c = m.findAttribute(Attributes.code());
                    if (c.isPresent() && c.get().codeLength() >= min) {
                        rows.add(String.format("%6d locals=%-4d stack=%-4d %s.%s", c.get().codeLength(),
                            c.get().maxLocals(), c.get().maxStack(),
                            cm.thisClass().asInternalName(), m.methodName().stringValue()));
                    }
                }
            }
        }
        Collections.sort(rows, Collections.reverseOrder());
        rows.forEach(System.out::println);
    }
}

